FUNCTION_BLOCK FB
VAR_INPUT
    tankLevel    : REAL;
    outletFlow   : REAL;
    inletPermit  : BOOL;
    resetBtn     : BOOL;
END_VAR
VAR_OUTPUT
    pumpRun          : BOOL;
    alarmHigh        : BOOL;
    alarmLow         : BOOL;
    outletValveOpen  : BOOL;
END_VAR
VAR
    prevResetBtn   : BOOL := FALSE;
    risingReset    : BOOL;
    activeAlarmHigh : BOOL := FALSE;
    activeAlarmLow  : BOOL := FALSE;
END_VAR

    // 计算复位按钮上升沿
    risingReset := resetBtn AND NOT prevResetBtn;

    // 更新上一周期复位按钮状态
    prevResetBtn := resetBtn;

    // 高液位报警检测（自保持）
    IF tankLevel >= 85.0 THEN
        activeAlarmHigh := TRUE;
    END_IF

    // 低液位报警检测（自保持）
    IF tankLevel <= 15.0 THEN
        activeAlarmLow := TRUE;
    END_IF

    // 复位逻辑：仅当无报警时上升沿才生效
    IF risingReset AND NOT activeAlarmHigh AND NOT activeAlarmLow THEN
        activeAlarmHigh := FALSE;
        activeAlarmLow  := FALSE;
    END_IF

    // 控制逻辑（报警优先）
    // 高液位报警时立即停止进料泵
    IF activeAlarmHigh THEN
        pumpRun := FALSE;
    ELSE
        // 无高液位报警时：液位<85%、有进料许可、无低液位报警则启动泵
        IF tankLevel < 85.0 AND inletPermit AND NOT activeAlarmLow THEN
            pumpRun := TRUE;
        ELSE
            pumpRun := FALSE;
        END_IF
    END_IF

    // 低液位报警时关闭出口阀
    IF activeAlarmLow THEN
        outletValveOpen := FALSE;
    ELSE
        // 无低液位报警时：液位>15%、无高液位报警则打开出口阀
        IF tankLevel > 15.0 AND NOT activeAlarmHigh THEN
            outletValveOpen := TRUE;
        ELSE
            outletValveOpen := FALSE;
        END_IF
    END_IF

    // 输出报警状态
    alarmHigh := activeAlarmHigh;
    alarmLow  := activeAlarmLow;
END_FUNCTION_BLOCK
